import {IOrderItem} from "../../../models/order";
import {getActiveFirmId} from "../../../api/config";

export const CREATE_ORDER_DRAFT_STORAGE_KEY = "createOrder";

export const getOrderDraftStorageKey = (orderId?: string) => {
    let userId = 'anonymous';
    try {const user = JSON.parse(window.localStorage.getItem('authUser') || 'null'); if (Number(user?.id) > 0) userId = String(user.id);} catch {}
    const scope = `${getActiveFirmId() || 'unselected'}:${userId}`;
    return orderId ? `editOrder:${scope}:${orderId}` : `${CREATE_ORDER_DRAFT_STORAGE_KEY}:${scope}`;
};

export interface CreateOrderDraft {
    orderItems?: IOrderItem[];
    [key: string]: unknown;
}

export const readCreateOrderDraft = (orderId?: string): CreateOrderDraft => {
    const storedOrder = window.localStorage.getItem(getOrderDraftStorageKey(orderId));

    if (!storedOrder) {
        return {};
    }

    try {
        return JSON.parse(storedOrder);
    } catch {
        return {};
    }
};

export const writeOrderItemsToCreateOrderDraft = (orderItems: IOrderItem[], orderId?: string) => {
    const draft = readCreateOrderDraft(orderId);
    window.localStorage.setItem(
        getOrderDraftStorageKey(orderId),
        JSON.stringify({...draft, orderItems}),
    );
};

export const clearCreateOrderDraft = (orderId?: string) => {
    window.localStorage.removeItem(getOrderDraftStorageKey(orderId));
};
