import {getApiErrorMessage} from "../../api/errors";
import QueryError from "../shared/QueryError";
import React, {useState} from "react";
import {Checkbox, FormControl, FormControlLabel, InputLabel, Link, MenuItem, Select} from "@mui/material";
import DeleteOutlineIcon from "@mui/icons-material/DeleteOutline";
import ClearIcon from "@mui/icons-material/Clear";
import {Link as RouterLink} from "react-router-dom";
import styledCom from "styled-components";
import {styled} from "@mui/material/styles";
import moment from "moment/moment";
import {IReadOrder} from "../../models/order";
import MyPagination from "../../ui/pagination/pagination";
import {useAppDispatch, useAppSelector} from "../../store/store";
import {setPageNumber} from "./orderSlice";
import CoreButton from "../../ui/buttons/coreButton";
import {useGetStatusesQuery} from "../shared/statuses/statusesApi";
import {
    useBulkDeleteOrdersMutation,
    useChangeOrderStatusMutation,
    useGetOrdersQuery,
} from "./createOrder/createOrderApi";
import Loader from "../../ui/loader/loader";
import {EmptyState, ToolbarActions} from "../../ui/commonStyled/commonStyled";
import {useTranslation} from "../../i18n";
import {toast} from "react-toastify";
import BulkDeleteDialog from "../shared/bulkDelete/BulkDeleteDialog";

const OrdersStack = styledCom.div({
    display: "grid",
    gap: "14px",
});

const SelectionToolbar = styledCom.div({
    display: "flex",
    alignItems: "center",
    justifyContent: "space-between",
    gap: "12px",
    marginBottom: "14px",
    padding: "10px 14px",
    background: "var(--color-surface)",
    border: "1px solid var(--color-border)",
    borderRadius: "14px",
    boxShadow: "var(--shadow-soft)",

    "@media (max-width: 760px)": {
        alignItems: "stretch",
        flexDirection: "column",
    },
});

const OrderMedia = styledCom.div({
    display: "grid",
    alignContent: "start",
});

const OrderCheckbox = styledCom.div({
    display: "flex",
    alignItems: "center",
    minHeight: "36px",
});

const OrderDiv = styledCom.article<{ $changed: boolean }>(({ $changed }) => ({
    display: "grid",
    gridTemplateColumns: "112px minmax(0, 1fr) 260px",
    gap: "18px",
    alignItems: "stretch",
    padding: "16px",
    borderRadius: "16px",
    background: $changed
        ? "var(--color-success-soft)"
        : "var(--color-surface)",
    border: $changed
        ? "1px solid var(--color-success-border)"
        : "1px solid var(--color-border)",
    boxShadow: "var(--shadow-soft)",
    transition: "transform 160ms ease, box-shadow 160ms ease, border-color 160ms ease",

    "&:hover": {
        transform: "translateY(-2px)",
        borderColor: $changed ? "var(--color-success-border)" : "var(--color-border-strong)",
        boxShadow: "var(--shadow-hover)",
    },

    "@media (max-width: 1040px)": {
        gridTemplateColumns: "96px minmax(0, 1fr)",
    },

    "@media (max-width: 680px)": {
        gridTemplateColumns: "1fr",
    },
}));

const OrderDetailsDiv = styledCom.div({
    display: "grid",
    gap: "10px",
    minWidth: 0,
});

const OrderStatusDiv = styledCom.div({
    display: "grid",
    alignContent: "start",
    gap: "10px",
    minWidth: 0,

    "@media (max-width: 1040px)": {
        gridColumn: "1 / -1",
        gridTemplateColumns: "minmax(0, 1fr) auto",
        alignItems: "center",
    },

    "@media (max-width: 680px)": {
        gridTemplateColumns: "1fr",
    },
});

const Image = styledCom.img({
    width: "112px",
    height: "112px",
    borderRadius: "14px",
    objectFit: "cover",
    background: "var(--color-surface-soft)",
    border: "1px solid var(--color-border)",

    "@media (max-width: 1040px)": {
        width: "96px",
        height: "96px",
    },

    "@media (max-width: 680px)": {
        width: "100%",
        height: "180px",
    },
});

const MainSpan = styledCom.span({
    color: "var(--color-primary)",
    fontWeight: 780,
});

const Span = styledCom.span({
    color: "var(--color-text)",
    fontWeight: 760,
});

const OrderTitle = styledCom.p({
    margin: 0,
    color: "var(--color-text)",
    fontSize: "18px",
    fontWeight: 780,
    lineHeight: 1.35,
});

const OrderText = styledCom.p({
    margin: 0,
    color: "var(--color-muted)",
    fontSize: "14px",
    lineHeight: 1.55,

    a: {
        color: "var(--color-primary)",
        fontWeight: 700,
        textDecoration: "none",
    },
});

const OrderActions = styledCom.div({
    display: "grid",
    gap: "8px",
    marginTop: "10px",

    a: {
        textDecoration: "none",
    },
});

const ProductSelectWrap = styledCom.div({
    width: "min(360px, 100%)",
    marginTop: "8px",
});

const StatusFormControl = styled(FormControl)({
    width: "100%",
});

const StyledSelect = styled(Select)({
    borderRadius: "10px",
    backgroundColor: "var(--color-surface)",
});

const OrderList = () => {
    const dispatch = useAppDispatch();
    const {orderParams} = useAppSelector((state) => state.order);
    const {data: ordersResponse, isLoading: areOrdersLoading, isError: isOrdersError, error: ordersError, refetch: refetchOrders} = useGetOrdersQuery(orderParams);
    const {data: orderStatuses = [], isLoading: areStatusesLoading, isError: isStatusesError, error: statusesError, refetch: refetchStatuses} = useGetStatusesQuery({});
    const [saveStatus, {isLoading: isSavingStatus}] = useChangeOrderStatusMutation();
    const [bulkDeleteOrders, {isLoading: isBulkDeleting}] = useBulkDeleteOrdersMutation();
    const [changedStatuses, setChangedStatuses] = useState<Record<number, number>>({});
    const [selectedIds, setSelectedIds] = useState<Set<number>>(() => new Set());
    const [bulkDeleteOpen, setBulkDeleteOpen] = useState(false);
    const {t, locale} = useTranslation();
    const orders = ordersResponse?.items || [];
    const metaData = ordersResponse?.metaData || null;
    const allPageSelected = orders.length > 0 && orders.every((order) => selectedIds.has(order.id));
    const somePageSelected = orders.some((order) => selectedIds.has(order.id));

    function changeOrderStatusHandler(orderId: number, orderStatusId: number | string) {
        setChangedStatuses((current) => ({
            ...current,
            [orderId]: Number(orderStatusId),
        }));
    }

    async function saveOrderStatus(orderId: number, orderStatusId: number) {
        try {
            await saveStatus({orderId, orderStatusId}).unwrap();
            setChangedStatuses((current) => {
                const next = {...current};
                delete next[orderId];
                return next;
            });
            toast.success(t("Статус заказа №{id} был изменён", {id: orderId}));
        } catch (failure) {
            toast.error(getApiErrorMessage(failure, t("Не удалось выполнить действие.")));
        }
    }

    function toggleOrderSelection(orderId: number) {
        setSelectedIds((current) => {
            const next = new Set(current);
            if (next.has(orderId)) {
                next.delete(orderId);
            } else {
                next.add(orderId);
            }
            return next;
        });
    }

    function togglePageSelection(checked: boolean) {
        setSelectedIds((current) => {
            const next = new Set(current);
            orders.forEach((order) => checked ? next.add(order.id) : next.delete(order.id));
            return next;
        });
    }

    async function bulkDeleteHandler() {
        try {
            const result = await bulkDeleteOrders({ids: Array.from(selectedIds)}).unwrap();
            setSelectedIds(new Set());
            setBulkDeleteOpen(false);
            toast.success(t("Deleted items: {count}", {count: result.deleted}));
        } catch (failure) {
            toast.error(getApiErrorMessage(failure, t("Не удалось выполнить действие.")));
        }
    }

    function formatData(order: IReadOrder) {
        return `${moment(order.createdDate).format("DD.MM.YYYY")}`;
    }

    if (areOrdersLoading || areStatusesLoading) {
        return <Loader/>;
    }

    if (isOrdersError) return <QueryError error={ordersError} onRetry={refetchOrders}/>;
    if (isStatusesError) return <QueryError error={statusesError} onRetry={refetchStatuses}/>;

    if (!orders || orders.length === 0) {
        return (
            <EmptyState>
                <strong>{t("Заказы не найдены")}</strong>
                <span>{t("Попробуйте изменить поиск или фильтры.")}</span>
            </EmptyState>
        );
    }

    return (
        <>
            <BulkDeleteDialog
                open={bulkDeleteOpen}
                selectedCount={selectedIds.size}
                isLoading={isBulkDeleting}
                onClose={() => setBulkDeleteOpen(false)}
                onConfirm={bulkDeleteHandler}
            />
            <SelectionToolbar>
                <FormControlLabel
                    control={(
                        <Checkbox
                            checked={allPageSelected}
                            indeterminate={!allPageSelected && somePageSelected}
                            onChange={(event) => togglePageSelection(event.target.checked)}
                        />
                    )}
                    label={t("Select all on this page")}
                />
                <ToolbarActions>
                    {selectedIds.size > 0 && (
                        <CoreButton
                            muiType="secondary"
                            text={t("Clear selection")}
                            leftIcon={<ClearIcon/>}
                            onClick={() => setSelectedIds(new Set())}
                        />
                    )}
                    <CoreButton
                        muiType="error"
                        text={t("Delete selected ({count})", {count: selectedIds.size})}
                        leftIcon={<DeleteOutlineIcon/>}
                        disabled={selectedIds.size === 0 || isBulkDeleting}
                        onClick={() => setBulkDeleteOpen(true)}
                    />
                </ToolbarActions>
            </SelectionToolbar>
            <OrdersStack>
                {orders.map((order: any) => {
                    const currentStatusId = changedStatuses[order.id]
                        ?? order.statusId
                        ?? orderStatuses.find((orderStatus: any) => orderStatus.name === order.status)?.id
                        ?? "";
                    const isStatusChanged = changedStatuses[order.id] !== undefined;

                    return (
                    <OrderDiv key={order.id} $changed={isStatusChanged}>
                        <OrderMedia>
                            <OrderCheckbox>
                                <Checkbox
                                    checked={selectedIds.has(order.id)}
                                    onChange={() => toggleOrderSelection(order.id)}
                                    inputProps={{
                                        "aria-label": t("Select order #{id}", {id: order.id}),
                                    }}
                                />
                            </OrderCheckbox>
                            <Image src={order.orderMainProductImage} alt={order.orderMainProductName}/>
                            <OrderActions>
                                <Link
                                    component={RouterLink}
                                    to={`/ordersManagement/editOrder/${order.id}`}
                                >
                                    <CoreButton
                                        muiType="edit"
                                        fullWidth
                                        text={t("Изменить")}
                                    />
                                </Link>
                                <Link
                                    component={RouterLink}
                                    to={`/ordersManagement/${order.id}`}
                                >
                                    <CoreButton muiType="info" fullWidth text={t("Подробнее")}/>
                                </Link>
                            </OrderActions>
                        </OrderMedia>

                        <OrderDetailsDiv>
                            <OrderTitle>
                                <MainSpan>{t("Заказ #{id}", {id: order.id})}</MainSpan> {t("от")} {formatData(order)}
                            </OrderTitle>
                            {order.orderItems.length <= 1 ? (
                                <OrderText>
                                    <Span>{t("Товар:")} </Span>{order.orderMainProductName}
                                </OrderText>
                            ) : (
                                <OrderText as="div">
                                    {t("В заказе {count} товара", {count: order.orderItems.length})}
                                    <ProductSelectWrap>
                                        <FormControl fullWidth size="small">
                                            <InputLabel>{t("Список товаров")}</InputLabel>
                                            <StyledSelect label={t("Список товаров")} defaultValue="">
                                                <MenuItem value="">
                                                    <em>{t("Выберите товар")}</em>
                                                </MenuItem>
                                                {order.orderItems.map((orderItem: any) => (
                                                    <MenuItem key={`${orderItem.itemType}:${orderItem.product}`} value={orderItem.product}>
                                                        {orderItem.itemName || orderItem.product}
                                                    </MenuItem>
                                                ))}
                                            </StyledSelect>
                                        </FormControl>
                                    </ProductSelectWrap>
                                </OrderText>
                            )}
                            <OrderText>
                                <Span>{t("Клиент:")} </Span>{order.customer.name},{" "}
                                <a href={`tel:${order.customer.phone}`}>{order.customer.phone}</a>
                                {order.customer.address ? `, ${t("адрес: {address}", {address: order.customer.address})}` : ""}
                            </OrderText>
                            <OrderText>
                                <Span>{t("Общая сумма:")} </Span>{order.totalSum.toLocaleString(locale, {minimumFractionDigits: 2, maximumFractionDigits: 2})} BYN
                            </OrderText>
                            <OrderText><Span>Ответственные: </Span>{order.responsibleUsers?.length ? order.responsibleUsers.map((user: {name: string}) => user.name).join(", ") : order.responsibleUserName || "Не назначены"}</OrderText>
                        </OrderDetailsDiv>

                        <OrderStatusDiv>
                            <StatusFormControl size="small">
                                <InputLabel>{t("Статус")}</InputLabel>
                                <StyledSelect
                                    label={t("Статус")}
                                    value={currentStatusId}
                                    onChange={(e: any) =>
                                        changeOrderStatusHandler(order.id, e.target.value)
                                    }
                                >
                                    {orderStatuses.map((orderStatus: any) => (
                                        <MenuItem key={orderStatus.id} value={orderStatus.id}>
                                            {orderStatus.name}
                                        </MenuItem>
                                    ))}
                                </StyledSelect>
                            </StatusFormControl>
                            <CoreButton
                                muiType="success"
                                fullWidth
                                text={isStatusChanged ? t("Сохранить статус") : t("Сохранить")}
                                disabled={!isStatusChanged || isSavingStatus}
                                onClick={() => saveOrderStatus(order.id, Number(currentStatusId))}
                            />
                        </OrderStatusDiv>
                    </OrderDiv>
                    );
                })}
            </OrdersStack>
            <MyPagination
                metaData={metaData}
                onPageChange={(page) => dispatch(setPageNumber(page))}
            />
        </>
    );
};

export default OrderList;
