import React, {useState} from "react";
import {
    Chip,
    Button,
    Collapse,
    IconButton,
    FormControl,
    InputAdornment,
    InputLabel,
    MenuItem,
    Select,
    TextField,
} from "@mui/material";
import SearchIcon from "@mui/icons-material/Search";
import RestartAltIcon from "@mui/icons-material/RestartAlt";
import FilterAltOutlinedIcon from "@mui/icons-material/FilterAltOutlined";
import TuneRoundedIcon from "@mui/icons-material/TuneRounded";
import ExpandMoreRoundedIcon from "@mui/icons-material/ExpandMoreRounded";
import CloseRoundedIcon from "@mui/icons-material/CloseRounded";
import styledCom from "styled-components";
import {setOrderParams} from "./orderSlice";
import {useAppDispatch, useAppSelector} from "../../store/store";
import {useGetStatusesQuery} from "../shared/statuses/statusesApi";
import {useTranslation} from "../../i18n";

interface OrderFiltersProps {
    searchTerm: string;
    onSearchTermChange: (value: string) => void;
}

const FilterPanel = styledCom.section({display: "grid", gap: "18px"});
const FilterHeader = styledCom.div({display: "flex", alignItems: "center", justifyContent: "space-between", gap: "12px", flexWrap: "wrap"});
const FilterTitle = styledCom.div({display: "flex", alignItems: "center", gap: "8px", color: "var(--color-text)", fontWeight: 700, fontSize: 13});
const FilterGrid = styledCom.div({
    display: "grid",
    gridTemplateColumns: "minmax(260px, 1.4fr) minmax(210px, 0.8fr) minmax(190px, 0.7fr)",
    gap: "12px",
    "@media (max-width: 1120px)": {gridTemplateColumns: "1fr 1fr"},
    "@media (max-width: 640px)": {gridTemplateColumns: "1fr"},
});
const RangeGrid = styledCom.div({
    display: "grid",
    gridTemplateColumns: "repeat(4, minmax(150px, 1fr)) minmax(120px, 0.6fr)",
    gap: "12px",
    "@media (max-width: 1120px)": {gridTemplateColumns: "1fr 1fr"},
    "@media (max-width: 640px)": {gridTemplateColumns: "1fr"},
});

const sortOptions = [
    {value: "dateDesc", label: "Newest first"},
    {value: "date", label: "Oldest first"},
    {value: "changeDateDesc", label: "Recently updated"},
    {value: "priceDesc", label: "Highest total first"},
    {value: "price", label: "Lowest total first"},
];

const OrderFilters = ({searchTerm, onSearchTermChange}: OrderFiltersProps) => {
    const dispatch = useAppDispatch();
    const {orderParams} = useAppSelector((state) => state.order);
    const {data: statuses = []} = useGetStatusesQuery({});
    const {t} = useTranslation();
    const [expanded, setExpanded] = useState(Boolean(orderParams.minTotal !== undefined || orderParams.maxTotal !== undefined || orderParams.createdFrom || orderParams.createdTo));
    const rangeCount = Number(orderParams.minTotal !== undefined) + Number(orderParams.maxTotal !== undefined) + Number(Boolean(orderParams.createdFrom)) + Number(Boolean(orderParams.createdTo));
    const activeFilterCount = orderParams.orderStatuses.length +
        Number(orderParams.minTotal !== undefined) +
        Number(orderParams.maxTotal !== undefined) +
        Number(Boolean(orderParams.createdFrom)) +
        Number(Boolean(orderParams.createdTo)) +
        Number(Boolean(searchTerm));

    const reset = () => {
        onSearchTermChange("");
        dispatch(setOrderParams({
            searchTerm: "",
            orderStatuses: [],
            minTotal: undefined,
            maxTotal: undefined,
            createdFrom: undefined,
            createdTo: undefined,
            orderBy: "dateDesc",
            pageSize: 25,
        }));
    };

    return (
        <FilterPanel aria-label={t("Order search filters")}>
            <FilterHeader>
                <FilterTitle>
                    <FilterAltOutlinedIcon fontSize="small"/>
                    {t("Order search filters")}
                    {activeFilterCount > 0 && <Chip size="small" label={activeFilterCount}/>}
                </FilterTitle>
                <Button size="small" startIcon={<RestartAltIcon/>} disabled={activeFilterCount === 0 && orderParams.orderBy === "dateDesc" && orderParams.pageSize === 25} onClick={reset}>{t("Reset filters")}</Button>
            </FilterHeader>
            <FilterGrid>
                <TextField
                    size="small"
                    value={searchTerm}
                    label={t("Customer, phone, product or service")}
                    onChange={(event) => onSearchTermChange(event.target.value)}
                    InputProps={{startAdornment: <InputAdornment position="start"><SearchIcon fontSize="small"/></InputAdornment>, endAdornment: searchTerm ? <InputAdornment position="end"><IconButton size="small" aria-label="Очистить поиск заказов" onClick={() => onSearchTermChange("")}><CloseRoundedIcon fontSize="small"/></IconButton></InputAdornment> : undefined}}
                />
                <FormControl size="small">
                    <InputLabel id="order-status-filter-label">{t("Statuses")}</InputLabel>
                    <Select
                        labelId="order-status-filter-label"
                        multiple
                        value={orderParams.orderStatuses}
                        label={t("Statuses")}
                        onChange={(event) => dispatch(setOrderParams({orderStatuses: event.target.value as string[]}))}
                        renderValue={(selected) => (
                            <span style={{display: "flex", gap: 4, flexWrap: "wrap"}}>
                                {(selected as string[]).map((status) => <Chip key={status} size="small" label={status}/>) }
                            </span>
                        )}
                    >
                        {statuses.map((status: any) => <MenuItem key={status.id} value={status.name}>{status.name}</MenuItem>)}
                    </Select>
                </FormControl>
                <FormControl size="small">
                    <InputLabel id="order-sort-filter-label">{t("Sort orders")}</InputLabel>
                    <Select labelId="order-sort-filter-label" value={orderParams.orderBy} label={t("Sort orders")} onChange={(event) => dispatch(setOrderParams({orderBy: String(event.target.value)}))}>
                        {sortOptions.map((option) => <MenuItem key={option.value} value={option.value}>{t(option.label)}</MenuItem>)}
                    </Select>
                </FormControl>
            </FilterGrid>
            <div style={{display: "flex", alignItems: "center", justifyContent: "space-between", flexWrap: "wrap", gap: 12, borderTop: "1px solid var(--color-border)", paddingTop: 10}}>
                <Button size="small" startIcon={<TuneRoundedIcon/>} endIcon={<ExpandMoreRoundedIcon sx={{transform: expanded ? "rotate(180deg)" : "none", transition: "transform 160ms"}}/>} aria-expanded={expanded} aria-controls="order-range-filters" onClick={() => setExpanded(value => !value)}>Период и сумма {rangeCount > 0 && <Chip size="small" color="primary" label={rangeCount} sx={{ml: 1}}/>}</Button>
                <span style={{fontSize: 11, color: "var(--color-muted)"}}>Фильтры применяются автоматически</span>
            </div>
            <Collapse in={expanded} id="order-range-filters">
            <RangeGrid>
                <TextField size="small" type="number" inputProps={{min: 0}} label={t("Total from")} value={orderParams.minTotal ?? ""} onChange={(event) => dispatch(setOrderParams({minTotal: event.target.value ? Number(event.target.value) : undefined}))}/>
                <TextField size="small" type="number" inputProps={{min: 0}} label={t("Total to")} value={orderParams.maxTotal ?? ""} onChange={(event) => dispatch(setOrderParams({maxTotal: event.target.value ? Number(event.target.value) : undefined}))}/>
                <TextField size="small" type="date" label={t("Created from")} value={orderParams.createdFrom ?? ""} InputLabelProps={{shrink: true}} onChange={(event) => dispatch(setOrderParams({createdFrom: event.target.value || undefined}))}/>
                <TextField size="small" type="date" label={t("Created to")} value={orderParams.createdTo ?? ""} InputLabelProps={{shrink: true}} onChange={(event) => dispatch(setOrderParams({createdTo: event.target.value || undefined}))}/>
                <FormControl size="small">
                    <InputLabel id="order-page-size-filter-label">{t("Per page")}</InputLabel>
                    <Select labelId="order-page-size-filter-label" value={orderParams.pageSize} label={t("Per page")} onChange={(event) => dispatch(setOrderParams({pageSize: Number(event.target.value)}))}>
                        {[25, 50, 100].map((pageSize) => <MenuItem key={pageSize} value={pageSize}>{pageSize}</MenuItem>)}
                    </Select>
                </FormControl>
            </RangeGrid>
            </Collapse>
            {rangeCount > 0 && <div style={{display: "flex", flexWrap: "wrap", gap: 6}} aria-label="Активные фильтры">
                {orderParams.minTotal !== undefined && <Chip size="small" color="primary" label={`${t("Total from")}: ${orderParams.minTotal}`} onDelete={() => dispatch(setOrderParams({minTotal: undefined}))}/>}
                {orderParams.maxTotal !== undefined && <Chip size="small" color="primary" label={`${t("Total to")}: ${orderParams.maxTotal}`} onDelete={() => dispatch(setOrderParams({maxTotal: undefined}))}/>}
                {orderParams.createdFrom && <Chip size="small" color="primary" label={`${t("Created from")}: ${orderParams.createdFrom}`} onDelete={() => dispatch(setOrderParams({createdFrom: undefined}))}/>}
                {orderParams.createdTo && <Chip size="small" color="primary" label={`${t("Created to")}: ${orderParams.createdTo}`} onDelete={() => dispatch(setOrderParams({createdTo: undefined}))}/>}
            </div>}
        </FilterPanel>
    );
};

export default OrderFilters;
