import React, {useEffect, useState} from "react";
import styledCom from "styled-components";
import AddIcon from "@mui/icons-material/Add";
import {NavLink} from "react-router-dom";
import {useAppDispatch, useAppSelector} from "../../store/store";
import {setOrderParams} from "./orderSlice";
import OrderFilters from "./orderFilters";
import OrderList from "./orderList";
import CoreButton from "../../ui/buttons/coreButton";
import useDebounce from "../../hooks/useDebounce";
import {
    MainDiv,
    PageHeader,
    PageSubtitle,
    PageTitle,
    PageTitleGroup,
    Surface,
} from "../../ui/commonStyled/commonStyled";
import {useTranslation} from "../../i18n";
import {clearCreateOrderDraft} from "./createOrder/createOrderDraft";

const SearchSurface = styledCom(Surface)({marginBottom: "16px"});

const OrdersManagement = () => {
    const dispatch = useAppDispatch();
    const {orderParams} = useAppSelector((state) => state.order);
    const [searchTerm, setSearchTerm] = useState(orderParams.searchTerm);
    const debouncedSearch = useDebounce(searchTerm);
    const {t} = useTranslation();

    useEffect(() => {
        if (debouncedSearch !== orderParams.searchTerm) {
            dispatch(setOrderParams({searchTerm: debouncedSearch}));
        }
    }, [debouncedSearch, dispatch, orderParams.searchTerm]);

    return (
        <MainDiv>
            <PageHeader>
                <PageTitleGroup>
                    <PageTitle>{t("Заказы")}</PageTitle>
                    <PageSubtitle>
                        {t("Быстрый обзор клиентских заказов, статусов, сумм и действий по обработке.")}
                    </PageSubtitle>
                </PageTitleGroup>
                <NavLink
                    to="createOrder"
                    style={{textDecoration: "none"}}
                    onClick={() => clearCreateOrderDraft()}
                >
                    <CoreButton
                        muiType="success"
                        leftIcon={<AddIcon/>}
                        text={t("Создать заказ")}
                    />
                </NavLink>
            </PageHeader>

            <SearchSurface>
                <OrderFilters searchTerm={searchTerm} onSearchTermChange={setSearchTerm}/>
            </SearchSurface>

            <OrderList/>
        </MainDiv>
    );
};

export default OrdersManagement;
