import React from "react";
import {Pagination} from "@mui/material";
import styledCom from "styled-components";
import {MetaData} from "../../models/pagination";
import {useTranslation} from "../../i18n";

const PaginationDiv = styledCom.nav({
    display: "flex",
    alignItems: "center",
    justifyContent: "space-between",
    gap: "12px",
    marginTop: "16px",
    padding: "12px 14px",
    backgroundColor: "var(--color-surface)",
    border: "1px solid var(--color-border)",
    borderRadius: "14px",
    boxShadow: "var(--shadow-soft)",

    "@media (max-width: 760px)": {
        display: "grid",
        justifyItems: "center",
    },
});

const PaginationMeta = styledCom.p({
    margin: 0,
    color: "var(--color-muted)",
    fontSize: "13px",
    fontWeight: 700,
});

interface PaginationProps {
    metaData: MetaData | null;
    onPageChange?: (page: number) => void;
}

const MyPagination = ({metaData, onPageChange}: PaginationProps) => {
    const {t} = useTranslation();
    const from = metaData ? (metaData.currentPage - 1) * metaData.pageSize + 1 : 0;
    const to = metaData
        ? Math.min(metaData.currentPage * metaData.pageSize, metaData.totalCount)
        : 0;

    return (
        <PaginationDiv aria-label={t("Пагинация заказов")}>
            <PaginationMeta>
                {metaData
                    ? t("Показано {from}-{to} из {total}", {from, to, total: metaData.totalCount})
                    : t("Нет данных")}
            </PaginationMeta>
            <Pagination
                color="primary"
                count={metaData?.totalPages || 0}
                page={metaData?.currentPage || 1}
                shape="rounded"
                onChange={(_event, page) => onPageChange?.(page)}
            />
        </PaginationDiv>
    );
};

export default MyPagination;
