import React from "react";
import {
    Button,
    Dialog,
    DialogActions,
    DialogContent,
    DialogContentText,
    DialogTitle,
} from "@mui/material";
import {useTranslation} from "../../../i18n";
import {maximumBulkDeleteItems} from "../../../models/bulkDelete";

interface BulkDeleteDialogProps {
    open: boolean;
    selectedCount: number;
    isLoading?: boolean;
    onClose: () => void;
    onConfirm: () => void | Promise<void>;
}

const BulkDeleteDialog = ({
                              open,
                              selectedCount,
                              isLoading = false,
                              onClose,
                              onConfirm,
                          }: BulkDeleteDialogProps) => {
    const {t} = useTranslation();
    const exceedsMaximum = selectedCount > maximumBulkDeleteItems;

    return (
        <Dialog open={open} onClose={isLoading ? undefined : onClose}>
            <DialogTitle>{t("Delete selected items?")}</DialogTitle>
            <DialogContent>
                <DialogContentText>
                    {t("You are about to delete {count} selected items. This action cannot be undone.", {
                        count: selectedCount,
                    })}
                </DialogContentText>
                {exceedsMaximum && (
                    <DialogContentText color="error">
                        {t("You can delete no more than 500 items at once.")}
                    </DialogContentText>
                )}
            </DialogContent>
            <DialogActions>
                <Button onClick={onClose} disabled={isLoading}>{t("Cancel")}</Button>
                <Button
                    color="error"
                    onClick={onConfirm}
                    disabled={isLoading || selectedCount === 0 || exceedsMaximum}
                    autoFocus
                >
                    {isLoading ? t("Deleting...") : t("Delete selected ({count})", {count: selectedCount})}
                </Button>
            </DialogActions>
        </Dialog>
    );
};

export default BulkDeleteDialog;
